const yen = n => '¥' + n.toLocaleString();
const range = (a,b) => a === b ? yen(a) : yen(a) + '〜' + yen(b);

// 万単位表示(¥40,000 → 4万円, ¥45,000 → 4.5万円)
function man(n) {
  if (Math.abs(n) >= 10000) {
    const v = n / 10000;
    return (v % 1 === 0 ? v : v.toFixed(1)) + '万円';
  }
  return yen(n);
}
function manRange(a, b) {
  if (a === b) return man(a);
  return man(a) + '〜' + man(b);
}

// Easy mode helpers
function judgeJP(j) {
  return { GO: ['🟢', '買っていい!', 'おトクに仕入れられる'], COND: ['🟡', 'ちょい検討', '条件次第でアリ'], NO: ['🔴', 'やめとけ', '利益出にくいかも'] }[j];
}

// Mode state
let mode = localStorage.getItem('rmb_mode') || 'easy';

const STORAGE_KEYS = { fav: 'rmb_favs', hist: 'rmb_history', tut: 'rmb_tutorial_done' };
function getFavs() { try { return JSON.parse(localStorage.getItem(STORAGE_KEYS.fav) || '[]'); } catch { return []; } }
function setFavs(arr) { localStorage.setItem(STORAGE_KEYS.fav, JSON.stringify(arr)); updateBadges(); }
function getHist() { try { return JSON.parse(localStorage.getItem(STORAGE_KEYS.hist) || '[]'); } catch { return []; } }
function setHist(arr) { localStorage.setItem(STORAGE_KEYS.hist, JSON.stringify(arr.slice(0, 30))); updateBadges(); }
function addHist(id) {
  const h = getHist().filter(x => x !== id);
  h.unshift(id);
  setHist(h);
}
function toggleFav(id) {
  const f = getFavs();
  const idx = f.indexOf(id);
  if (idx >= 0) { f.splice(idx, 1); setFavs(f); return false; }
  f.unshift(id);
  setFavs(f);
  return true;
}
function updateBadges() {
  const fc = getFavs().length;
  const hc = getHist().length;
  document.getElementById('fav-count').textContent = fc > 0 ? fc : '';
  document.getElementById('hist-count').textContent = hc > 0 ? hc : '';
}
function toast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('active');
  clearTimeout(t._t);
  t._t = setTimeout(() => t.classList.remove('active'), 1600);
}

// ===== Brand mapping =====
const BRAND_MAP_JP = { 'ヴィトン': 'ルイヴィトン', 'シャネル': 'シャネル', 'エルメス': 'エルメス' };
const BRAND_MAP_EN = { 'ヴィトン': 'Louis Vuitton', 'シャネル': 'Chanel', 'エルメス': 'Hermes' };

function cleanModel(model) {
  return model.replace(/\s*\(猪川\)/g, '').replace(/\s*\(過去\)/g, '').trim();
}

// ===== Site config & URL builders =====
const SITES = {
  mercari: {
    icon: '🛒', name: 'メルカリ', cls: 'mercari',
    note: '国内最大・素人出品が多くお宝発掘向き',
    build: (d, opts) => {
      const params = new URLSearchParams();
      const kw = BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model);
      params.set('keyword', kw);
      if (opts.status === 'sold') params.set('status', 'sold_out');
      else if (opts.status === 'onsale') params.set('status', 'on_sale');
      if (opts.conditions && opts.conditions.length) {
        opts.conditions.forEach(c => params.append('item_condition_id', c));
      }
      if (opts.priceMin) params.set('price_min', opts.priceMin);
      if (opts.priceMax) params.set('price_max', opts.priceMax);
      return 'https://jp.mercari.com/search?' + params.toString();
    },
    getKeyword: d => BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model),
    conditions: [
      { id: '1', lbl: '新品' },
      { id: '2', lbl: '未使用に近い' },
      { id: '3', lbl: '目立った傷なし' },
      { id: '4', lbl: 'やや傷あり' }
    ]
  },
  yahoo: {
    icon: '🇯🇵', name: 'ヤフオク', cls: 'yahoo',
    note: '業者参入多くて値崩れ起きにくい・落札相場が分かる',
    build: (d, opts) => {
      const params = new URLSearchParams();
      const kw = BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model);
      params.set('p', kw);
      // 完売(落札済み)→終了オークションタブで見る/このURLはオークション検索
      if (opts.status === 'sold') {
        // 落札相場URL(別ドメイン)
        return 'https://aucfan.com/search1/q-' + encodeURIComponent(kw) + '/s-mix/';
      }
      // 即決のみ
      if (opts.buynow) params.set('fixed', '1');
      // 価格
      if (opts.priceMin) params.set('aucminprice', opts.priceMin);
      if (opts.priceMax) params.set('aucmaxprice', opts.priceMax);
      // 新品/中古 (used=新品以外, new=新品)
      if (opts.itemStatus === 'new') params.set('istatus', '1');
      else if (opts.itemStatus === 'used') params.set('istatus', '2');
      return 'https://auctions.yahoo.co.jp/search/search?' + params.toString();
    },
    getKeyword: d => BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model),
    conditions: null,
    extra: 'yahoo'
  },
  rakuma: {
    icon: '🛍', name: 'ラクマ', cls: 'rakuma',
    note: '楽天ポイント連携・販売手数料安め',
    build: (d, opts) => {
      const params = new URLSearchParams();
      const kw = BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model);
      params.set('keyword', kw);
      // 売切表示
      if (opts.status === 'sold') params.set('transaction', '1');
      else if (opts.status === 'onsale') params.set('transaction', '0');
      // 価格
      if (opts.priceMin) params.set('min', opts.priceMin);
      if (opts.priceMax) params.set('max', opts.priceMax);
      // 商品状態 1=新品 2=未使用 3=未使用に近い 4=目立った傷や汚れなし 5=やや傷や汚れあり
      if (opts.conditions && opts.conditions.length) {
        opts.conditions.forEach(c => params.append('itemConditionType', c));
      }
      return 'https://fril.jp/s?' + params.toString();
    },
    getKeyword: d => BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model),
    conditions: [
      { id: '1', lbl: '新品' },
      { id: '3', lbl: '未使用に近い' },
      { id: '4', lbl: '目立った傷なし' },
      { id: '5', lbl: 'やや傷あり' }
    ]
  },
  yfrima: {
    icon: '💰', name: 'Y!フリマ', cls: 'yfrima',
    note: '匿名配送・PayPay連携、フリマ系の中で値段比較',
    build: (d, opts) => {
      const params = new URLSearchParams();
      const kw = BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model);
      // sortは省略
      if (opts.status === 'sold') params.set('sold_status', 'soldout');
      else if (opts.status === 'onsale') params.set('sold_status', 'unsold');
      if (opts.priceMin) params.set('price_min', opts.priceMin);
      if (opts.priceMax) params.set('price_max', opts.priceMax);
      // 商品状態 1=新品 2=未使用に近い 3=目立った傷や汚れなし
      if (opts.conditions && opts.conditions.length) {
        opts.conditions.forEach(c => params.append('item_condition_id', c));
      }
      const qs = params.toString();
      return 'https://paypayfleamarket.yahoo.co.jp/search/' + encodeURIComponent(kw) + (qs ? '?' + qs : '');
    },
    getKeyword: d => BRAND_MAP_JP[d.brand] + ' ' + cleanModel(d.model),
    conditions: [
      { id: '1', lbl: '新品' },
      { id: '2', lbl: '未使用に近い' },
      { id: '3', lbl: '目立った傷なし' }
    ]
  },
  ebay: {
    icon: '🌍', name: 'eBay', cls: 'ebay',
    note: '海外相場・ヴィトン/エルメス強い、輸出視野なら必須',
    build: (d, opts) => {
      const params = new URLSearchParams();
      const kw = BRAND_MAP_EN[d.brand] + ' ' + cleanModel(d.model);
      params.set('_nkw', kw);
      // LH_Sold=1 で売却済み, LH_Complete=1 で全完了 (両方=売切相場)
      if (opts.status === 'sold') {
        params.set('LH_Sold', '1');
        params.set('LH_Complete', '1');
      }
      // 価格 (USDに換算は省略、円のまま入れる)
      if (opts.priceMin) params.set('_udlo', opts.priceMin);
      if (opts.priceMax) params.set('_udhi', opts.priceMax);
      // 商品状態 1000=New, 3000=Used (eBay condition IDs)
      if (opts.conditions && opts.conditions.length) {
        params.set('LH_ItemCondition', opts.conditions.join('|'));
      }
      return 'https://www.ebay.com/sch/i.html?' + params.toString();
    },
    getKeyword: d => BRAND_MAP_EN[d.brand] + ' ' + cleanModel(d.model),
    conditions: [
      { id: '1000', lbl: 'New' },
      { id: '1500', lbl: 'Open box' },
      { id: '3000', lbl: 'Used' },
      { id: '7000', lbl: 'For parts' }
    ]
  }
};

function judgeLabel(j) { return { GO: 'GO', COND: 'CHECK', NO: 'NO' }[j]; }
function judgeClass(j) { return { GO: 'go', COND: 'cond', NO: 'no' }[j]; }

// Easy mode card
function renderEasyCard(d) {
  const j = judgeClass(d.judge);
  const [emoji, label, sub] = judgeJP(d.judge);
  const isFav = getFavs().includes(d.id);
  const tags = [];
  if (d.kanchou_pick) tags.push('<span class="easy-tag kanchou">⭐館長おすすめ</span>');
  if (d.modern === true) tags.push('<span class="easy-tag modern">🆕 新しめモデル</span>');
  else if (d.modern === false) tags.push('<span class="easy-tag vintage">📜 古めのモデル</span>');
  if (d.season) tags.push(`<span class="easy-tag season">🌿 ${d.season}</span>`);

  const profitClass = d.profit_jpy < 0 ? 'val loss' : 'val';
  const actionMsg = {
    GO: 'タップして相場確認 → メルカリなどで探そう',
    COND: 'タップして相場確認 → 利益出るか吟味',
    NO: 'タップして相場確認 → 仕入れは見送り推奨'
  }[d.judge];

  return `
    <div class="card easy ${j} ${isFav ? 'is-fav' : ''}" data-id="${d.id}">
      <div class="fav-icon">⭐</div>
      <div class="easy-signal ${j}">
        <span class="easy-signal-emoji">${emoji}</span>
        <span class="easy-signal-text">${label}</span>
      </div>
      <div class="easy-meta">${d.brand}</div>
      <div class="easy-name">${d.model}</div>
      ${tags.length ? `<div class="easy-tags">${tags.join('')}</div>` : ''}
      <div class="easy-money">
        <div class="easy-money-row"><span class="lbl">💰 仕入れ目安</span><span class="val">${manRange(d.buy_min, d.buy_max)}</span></div>
        <div class="easy-money-row"><span class="lbl">🏷 売却目安</span><span class="val">${manRange(d.sell_min, d.sell_max)}</span></div>
        <div class="easy-money-row profit"><span class="lbl">📈 もうけ目安</span><span class="${profitClass}">${man(d.profit_jpy)}</span></div>
      </div>
      <div class="easy-action ${j}">👉 ${actionMsg}</div>
    </div>`;
}

// Expert mode card
function renderExpertCard(d) {
  const j = judgeClass(d.judge);
  const lbl = judgeLabel(d.judge);
  const tags = [];
  const isFav = getFavs().includes(d.id);

  if (d.kanchou_pick) tags.push('<span class="tag kanchou">⭐館長</span>');
  if (d.leather_tag) {
    const tier = d.leather_tier;
    const marker = tier === 'S' ? '★S' : (tier === 'D' ? '❌' : '✓');
    tags.push(`<span class="tag tier-${tier.toLowerCase()}">${marker} ${d.leather_tag}</span>`);
  }
  if (d.modern === true) tags.push(`<span class="tag modern">🆕 近年</span>`);
  else if (d.modern === false) tags.push(`<span class="tag vintage">📜 ビンテージ</span>`);
  if (d.season) tags.push(`<span class="tag season">🌿 ${d.season}</span>`);
  if (d.source === '過去') {
    tags.push(`<span class="tag source-past">📊 過去${d.past_count}件</span>`);
  }

  const profitClass = d.profit_jpy < 0 ? 'pv pv-loss' : 'pv';

  return `
    <div class="card ${j} ${isFav ? 'is-fav' : ''}" data-id="${d.id}">
      <div class="fav-icon">⭐</div>
      <div class="card-head">
        <div class="card-title">
          <div class="card-meta">${d.brand}${d.leather_tag ? ' · ' + d.leather_tag : ''}</div>
          <div class="card-name">${d.model}</div>
        </div>
        <div class="judge-badge ${j}">
          <div>${lbl}</div>
          <div class="rate">${d.profit_rate >= 0 ? '+' : ''}${d.profit_rate}%</div>
        </div>
      </div>
      <div class="tags">${tags.join('')}</div>
      <div class="prices">
        <div class="price-box buy"><div class="pl">仕入</div><div class="pv">${range(d.buy_min, d.buy_max)}</div></div>
        <div class="price-box sell"><div class="pl">売却</div><div class="pv">${range(d.sell_min, d.sell_max)}</div></div>
        <div class="price-box profit"><div class="pl">利益</div><div class="${profitClass}">${yen(d.profit_jpy)}</div></div>
      </div>
      <div class="tap-hint">タップで5サイト横断リサーチ →</div>
    </div>`;
}

function apply() {
  const brand = document.querySelector('.brand-row .tab.active').dataset.brand;
  const catTab = document.querySelector('.cat-row .tab.active');
  const cat = (mode === 'expert' && catTab) ? catTab.dataset.cat : 'all';
  const sortTab = document.querySelector('.sort.active');
  const sortBy = (mode === 'expert' && sortTab) ? sortTab.dataset.sort : 'default';
  const q = document.getElementById('search').value.trim().toLowerCase();
  let f = [...DATA];

  if (brand === 'kanchou') f = f.filter(d => d.kanchou_pick);
  else if (brand !== 'all') f = f.filter(d => d.brand === brand);

  if (cat === 'GO') f = f.filter(d => d.judge === 'GO');
  else if (cat === 'COND') f = f.filter(d => d.judge === 'COND');
  else if (cat === 'NO') f = f.filter(d => d.judge === 'NO');
  else if (cat === '近年') f = f.filter(d => d.modern === true);
  else if (cat === 'ビンテージ') f = f.filter(d => d.modern === false);
  else if (cat === '強柄') f = f.filter(d => ['S','A'].includes(d.leather_tier));
  else if (cat === '季節性') f = f.filter(d => d.season);

  if (q) {
    f = f.filter(d => (d.brand + ' ' + d.model + ' ' + (d.leather_tag||'')).toLowerCase().includes(q));
  }

  if (sortBy === 'default') {
    f.sort((a, b) => {
      const ja = { GO: 0, COND: 1, NO: 2 }[a.judge];
      const jb = { GO: 0, COND: 1, NO: 2 }[b.judge];
      const ka = a.kanchou_pick && a.judge === 'GO' ? 0 : 1;
      const kb = b.kanchou_pick && b.judge === 'GO' ? 0 : 1;
      if (ka !== kb) return ka - kb;
      if (ja !== jb) return ja - jb;
      return b.profit_rate - a.profit_rate;
    });
  } else {
    const sorters = {
      rate: (a,b) => b.profit_rate - a.profit_rate,
      profit: (a,b) => b.profit_jpy - a.profit_jpy,
      buy_asc: (a,b) => a.buy_min - b.buy_min,
      sell: (a,b) => b.sell_max - a.sell_max,
      count: (a,b) => b.past_count - a.past_count
    };
    f.sort(sorters[sortBy]);
  }

  document.getElementById('stat-total').textContent = f.length;
  document.getElementById('stat-go').textContent = f.filter(d => d.judge==='GO').length;
  document.getElementById('stat-cond').textContent = f.filter(d => d.judge==='COND').length;
  document.getElementById('stat-no').textContent = f.filter(d => d.judge==='NO').length;

  const list = document.getElementById('list');
  const renderer = mode === 'easy' ? renderEasyCard : renderExpertCard;
  list.innerHTML = f.length ? f.map(renderer).join('') : '<div class="empty">該当モデルなし</div>';
}

// ===== Modal =====
let currentModel = null;
let activeSite = 'mercari';
let expertDetailsOpen = false;
let siteState = {
  mercari: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
  yahoo: { status: 'all', buynow: false, itemStatus: 'all', priceMin: '', priceMax: '' },
  rakuma: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
  yfrima: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
  ebay: { status: 'all', conditions: [], priceMin: '', priceMax: '' }
};

function resetSiteState() {
  siteState = {
    mercari: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
    yahoo: { status: 'all', buynow: false, itemStatus: 'all', priceMin: '', priceMax: '' },
    rakuma: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
    yfrima: { status: 'all', conditions: [], priceMin: '', priceMax: '' },
    ebay: { status: 'all', conditions: [], priceMin: '', priceMax: '' }
  };
}

function openModal(d) {
  currentModel = d;
  resetSiteState();
  activeSite = 'mercari';
  expertDetailsOpen = false;

  document.getElementById('modal-title').textContent = d.model;
  document.getElementById('modal-sub').textContent = `${d.brand}${d.leather_tag ? ' · ' + d.leather_tag : ''}`;
  renderModalBody();
  document.getElementById('modal-backdrop').classList.add('active');
  document.getElementById('modal').classList.add('active');
  document.body.style.overflow = 'hidden';
  addHist(d.id);
}
function closeModal() {
  document.getElementById('modal-backdrop').classList.remove('active');
  document.getElementById('modal').classList.remove('active');
  document.body.style.overflow = '';
  currentModel = null;
}

function renderSiteFilters(siteKey) {
  const site = SITES[siteKey];
  const state = siteState[siteKey];
  let html = '';

  // 表示切替(売切/販売中)
  html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:8px;">表示</div>`;
  html += `<div class="chip-row compact">`;
  html += `<div class="chip status-chip ${state.status === 'all' ? 'active' : ''}" data-status="all">全件</div>`;
  if (siteKey === 'yahoo') {
    html += `<div class="chip status-chip ${state.status === 'sold' ? 'active' : ''}" data-status="sold">落札相場(aucfan)</div>`;
    html += `<div class="chip status-chip ${state.status === 'onsale' ? 'active' : ''}" data-status="onsale">出品中</div>`;
  } else {
    html += `<div class="chip status-chip ${state.status === 'sold' ? 'active' : ''}" data-status="sold">売切のみ</div>`;
    html += `<div class="chip status-chip ${state.status === 'onsale' ? 'active' : ''}" data-status="onsale">販売中のみ</div>`;
  }
  html += `</div>`;

  // ヤフオク独自:即決
  if (siteKey === 'yahoo' && state.status !== 'sold') {
    html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:10px;">オプション</div>`;
    html += `<div class="chip-row compact">`;
    html += `<div class="chip buynow-chip ${state.buynow ? 'active' : ''}">即決のみ</div>`;
    html += `</div>`;
    html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:10px;">商品状態</div>`;
    html += `<div class="chip-row compact">`;
    html += `<div class="chip ystatus-chip ${state.itemStatus === 'all' ? 'active' : ''}" data-ystatus="all">全て</div>`;
    html += `<div class="chip ystatus-chip ${state.itemStatus === 'new' ? 'active' : ''}" data-ystatus="new">新品</div>`;
    html += `<div class="chip ystatus-chip ${state.itemStatus === 'used' ? 'active' : ''}" data-ystatus="used">中古</div>`;
    html += `</div>`;
  }

  // 品質フィルタ(他サイト)
  if (site.conditions) {
    html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:10px;">品質(複数選択可)</div>`;
    html += `<div class="chip-row compact">`;
    site.conditions.forEach(c => {
      html += `<div class="chip cond-chip ${state.conditions.includes(c.id) ? 'active' : ''}" data-cond="${c.id}">${c.lbl}</div>`;
    });
    html += `</div>`;
  }

  // 価格レンジ
  const ccy = siteKey === 'ebay' ? 'US$' : '¥';
  html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:10px;">価格レンジ(${ccy})</div>`;
  html += `<div class="range-row">`;
  html += `<input type="number" class="range-input" id="price-min" placeholder="最小" value="${state.priceMin}">`;
  html += `<span class="range-sep">〜</span>`;
  html += `<input type="number" class="range-input" id="price-max" placeholder="最大" value="${state.priceMax}">`;
  html += `</div>`;

  // プリセット(eBay以外、国内通貨)
  if (siteKey !== 'ebay') {
    const d = currentModel;
    const presets = [];
    if (d.buy_min) presets.push({ lbl: '仕入±20%', min: Math.floor(d.buy_min * 0.8), max: Math.floor((d.buy_max || d.buy_min) * 1.2) });
    if (d.sell_min) presets.push({ lbl: '売却帯', min: d.sell_min, max: d.sell_max });
    presets.push({ lbl: 'クリア', min: '', max: '' });
    html += `<div class="range-preset">`;
    presets.forEach((p, i) => {
      html += `<button class="preset-btn" data-preset="${i}" data-pmin="${p.min}" data-pmax="${p.max}">${p.lbl}</button>`;
    });
    html += `</div>`;
  } else {
    html += `<div class="range-preset">`;
    html += `<button class="preset-btn" data-preset-ebay="0" data-pmin="" data-pmax="">クリア</button>`;
    html += `</div>`;
  }

  // 検索ワード
  const keyword = site.getKeyword(currentModel);
  html += `<div style="font-size:11px;color:var(--ink-muted);margin-top:14px;">検索ワード</div>`;
  html += `<div class="query-preview">${keyword}</div>`;

  // メモ
  html += `<div class="site-note">💡 ${site.note}</div>`;

  return html;
}

